import copy, hashlib, importlib.util, json, shutil, tempfile
from pathlib import Path
import yaml
source=Path('outputs/personal-ai-skills').resolve()
spec=importlib.util.spec_from_file_location('v', source/'evaluations/validate_library.py')
v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
def refresh(root):
 p=root/'registry.yaml'; r=yaml.safe_load(p.read_text())
 for key in ('skills','adapters'):
  for e in r[key]:
   e['files']=[{'path':f.relative_to(root).as_posix(),'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in sorted((root/e['path']).rglob('*')) if f.is_file()]
 p.write_text(yaml.safe_dump(r,sort_keys=False));return r
cases={}
with tempfile.TemporaryDirectory() as tmp:
 base=Path(tmp)/'base';shutil.copytree(source,base);refresh(base)
 cases['normalized_hash_baseline']=v.validate(base)
 for case in ('support_removed','root_rogue_executable','evaluation_rogue_executable','fixture_unresolved','governance_extra_unregistered','wrongtype','duplicate_yaml','unhashable_yaml','symlink','hash_tamper','resource_link_missing','scripts_placeholder'):
  r=Path(tmp)/case;shutil.copytree(base,r)
  if case=='support_removed':
   reg=yaml.safe_load((r/'registry.yaml').read_text()); reg['skills']=[e for e in reg['skills'] if e['role']=='core']
   for name in ('grammar-checker-vi','scientific-thinking-literature-review'):shutil.rmtree(r/'skills'/name)
   (r/'registry.yaml').write_text(yaml.safe_dump(reg))
  elif case.endswith('rogue_executable'):
   p=r/('rogue.py' if case.startswith('root') else 'evaluations/rogue.py');p.write_text('raise RuntimeError("MUST NEVER RUN")\n');p.chmod(0o755)
  elif case=='fixture_unresolved':
   p=r/'evaluations/fixtures/fixture-catalog.json';obj=json.loads(p.read_text());obj['fixtures'][0]['path']='skills/missing/data.json';p.write_text(json.dumps(obj))
  elif case=='governance_extra_unregistered':(r/'governance/unregistered.py').write_text('raise RuntimeError("MUST NEVER RUN")\n')
  elif case=='wrongtype':
   reg=yaml.safe_load((r/'registry.yaml').read_text());reg['skills'][0]['role']=[];(r/'registry.yaml').write_text(yaml.safe_dump(reg))
  elif case=='duplicate_yaml':
   p=r/'registry.yaml';p.write_text(p.read_text()+'\nschema_version: 1\n')
  elif case=='unhashable_yaml':(r/'registry.yaml').write_text('? [a, b]\n: value\n')
  elif case=='symlink':(r/'external').symlink_to('/tmp')
  elif case=='hash_tamper':
   p=r/'skills/review-academic-thesis/SKILL.md';p.write_text(p.read_text()+'\nchanged\n')
  elif case=='resource_link_missing':
   p=r/'skills/review-academic-thesis/SKILL.md';p.write_text(p.read_text()+'\n[missing](references/not-here.md)\n');refresh(r)
  elif case=='scripts_placeholder':
   p=r/'skills/review-academic-thesis/scripts';shutil.rmtree(p);p.mkdir();(p/'placeholder.txt').write_text('TODO\n');refresh(r)
  cases[case]=v.validate(r)
 print(json.dumps(cases,ensure_ascii=False,indent=2))
